import { HashRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Navbar from './components/layout/Navbar';
import Footer from './components/layout/Footer';
import CorinthianPillar from './components/layout/CorinthianPillar';
import HomePage from './pages/HomePage';
import WallPage from './pages/WallPage';
import FilmsPage from './pages/FilmsPage';
import FilmDetailPage from './pages/FilmDetailPage';
import AboutPage from './pages/AboutPage';
import ProfilePage from './pages/ProfilePage';
import AlmanacPage from './pages/AlmanacPage';
import ListPage from './pages/ListPage';
import ListEditorPage from './pages/ListEditorPage';
import WatchedPage from './pages/WatchedPage';
import NotFoundPage from './pages/NotFoundPage';
import { ViewSettingsProvider } from './contexts/ViewSettingsContext';
import { OverridesProvider } from './contexts/OverridesContext';
import { TrophiesProvider } from './contexts/TrophiesContext';
import { ResponsesProvider } from './contexts/ResponsesContext';
import { ClubAuthProvider } from './auth/GoogleAuth';
import './index.css';
import ScrollToTop from './components/layout/ScrollToTop';
import PageTransition from './components/layout/PageTransition';
import ErrorBoundary from './components/common/ErrorBoundary';

function AppContent() {
    const location = useLocation();
    // The pages that raise a colonnade of their own — the home page's pair and
    // the log's single left pillar — go without the site-wide one behind them.
    // Two sets of columns in one view read as an accident rather than as
    // architecture.
    const drawsOwnPillars = location.pathname === '/' || location.pathname === '/log';

    return (
        // `isolate` gives the shell its own stacking context, so the backdrop's
        // z-index of -1 lands just above this background and below everything
        // else on the page. See `.site-backdrop` in index.css.
        //
        // The page runs edge to edge under iOS's bars (`viewport-fit=cover` in
        // index.html) so the backdrop can light them; the safe-area padding
        // keeps the nav out from under the status bar, the footer clear of the
        // home indicator, and both clear of the notch in landscape. Each inset
        // is 0 everywhere else.
        <div className="relative isolate flex flex-col min-h-screen bg-[#0f172b] font-se overflow-x-hidden pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)] pl-[env(safe-area-inset-left)] pr-[env(safe-area-inset-right)]">
            <div className="site-backdrop" aria-hidden="true" />

            {/* Background pillar wrapper - stretches to full document height */}
            {!drawsOwnPillars && (
                <div className="absolute inset-0 pointer-events-none z-0 overflow-hidden">
                    <CorinthianPillar
                        side="right"
                        flipped
                        width={250}
                        className="!opacity-[0.05]"
                    />
                </div>
            )}

            <Navbar />

            <main className="flex-grow w-full relative z-10">
                <PageTransition>
                    <Routes>
                        <Route path="/" element={<HomePage />} />
                        <Route path="/films" element={<FilmsPage />} />
                        {/* The club's activity in one chronological column. Reads
                the same four bundled files the pages below do; see
                `utils/wallUtils.ts`. */}
                        <Route path="/log" element={<WallPage />} />
                        {/* The page's old name, kept so bookmarks and shared links
                still land. `replace`, so Back doesn't bounce off it. */}
                        <Route path="/wall" element={<Navigate to="/log" replace />} />
                        <Route path="/films/:imdbId" element={<FilmDetailPage />} />
                        <Route path="/about" element={<AboutPage />} />
                        <Route path="/almanac" element={<AlmanacPage />} />
                        <Route path="/profile/:memberName" element={<ProfilePage />} />
                        {/* The static segments outrank `/lists/:listId`, so "new" is the
                editor rather than a list whose id happens to be "new". */}
                        <Route path="/lists/new" element={<ListEditorPage />} />
                        <Route path="/lists/:listId/edit" element={<ListEditorPage />} />
                        <Route path="/lists/:listId" element={<ListPage />} />
                        {/* A member's personal watch log. Not under /films: nothing here is
                a club film, and the two must never share a surface. */}
                        <Route path="/watched/:memberName" element={<WatchedPage />} />
                        <Route path="*" element={<NotFoundPage />} />
                    </Routes>
                </PageTransition>
            </main>

            <Footer />
        </div>
    );
}

function App() {
    if (import.meta.hot) {
        import.meta.hot.accept();
    }

    return (
        <ViewSettingsProvider>
            {/* Holds an editing session in memory. Mounting it costs nothing on an
          ordinary page view: no script loads and no request is made until a
          member opens an editing surface and signs in. */}
            <ClubAuthProvider>
                {/* One fetch of `overrides.json` for the whole session, rather than
              one per film page. Inert until someone signs in. */}
                <OverridesProvider>
                    {/* The club's trophies, serving the bundled file until a member
                  signs in and the live one is worth fetching. */}
                    <TrophiesProvider>
                        {/* Reactions and comments on log entries. Fetched live for
                      everyone, but only once something on the page shows one. */}
                        <ResponsesProvider>
                            <Router>
                                <ScrollToTop />
                                <ErrorBoundary>
                                    <AppContent />
                                </ErrorBoundary>
                            </Router>
                        </ResponsesProvider>
                    </TrophiesProvider>
                </OverridesProvider>
            </ClubAuthProvider>
        </ViewSettingsProvider>
    );
}

export default App;
